css:
/* The Jagged Frontier (Express 2027) v2.0.0
   Night-atlas theme. Every text colour holds 7:1 or more against every surface it sits on
   (WCAG 2.2 AAA 1.4.6, measured): text 14.3-17.4, text-2 10.7-13.0, text-3 8.6-10.5,
   accents 9.1-12.9, button and selected-option text 11.5. Text never sits on a gradient. */

.jagged-sim-container {
    --jf-bg: #0a1120;
    --jf-surface: #101a2c;
    --jf-surface-2: #0c1526;
    --jf-surface-3: #17243b;
    --jf-sel-bg: #1f3354;
    --jf-line: #2b3d5c;
    --jf-line-strong: #7489ad;
    --jf-text: #f3f6fb;
    --jf-text-2: #cdd7e7;
    --jf-text-3: #b4c2d8;
    --jf-amber: #ffcf70;
    --jf-amber-fill: #ffc24d;
    --jf-amber-fill-hover: #ffd47a;
    --jf-on-amber: #1b1300;
    --jf-cyan: #93dbff;
    --jf-green: #93e6b5;
    --jf-red: #ffb8b8;
    --jf-violet: #cdbdff;
    --jf-focus: #ffffff;
    --jf-radius: 14px;
    --jf-radius-sm: 10px;
    --jf-s1: 4px;
    --jf-s2: 8px;
    --jf-s3: 12px;
    --jf-s4: 16px;
    --jf-s5: 24px;
    --jf-s6: 32px;
    --jf-font: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

    position: relative;
    color-scheme: dark;
    font-family: var(--jf-font);
    font-size: 1rem;
    line-height: 1.6;
    color: var(--jf-text);
    background-color: var(--jf-bg);
    background-image:
        repeating-radial-gradient(circle at 18% 12%, rgba(147, 219, 255, 0.045) 0 1px, transparent 1px 34px),
        repeating-radial-gradient(circle at 86% 78%, rgba(255, 207, 112, 0.035) 0 1px, transparent 1px 42px);
    padding: var(--jf-s5);
    border-radius: 18px;
    min-height: 100vh;
    text-align: left;
}
.jagged-sim-container *,
.jagged-sim-container *::before,
.jagged-sim-container *::after { box-sizing: border-box; }
.jagged-sim-container [hidden] { display: none !important; }

.jagged-sim-container .jf-sr {
    position: absolute !important;
    width: 1px; height: 1px;
    padding: 0; margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Typography */
.jagged-sim-container h1,
.jagged-sim-container h2,
.jagged-sim-container h3 {
    color: var(--jf-text);
    font-family: var(--jf-font);
    line-height: 1.25;
    letter-spacing: 0;
    margin: 0 0 var(--jf-s3);
    font-weight: 750;
}
.jagged-sim-container h2 { font-size: 1.3rem; }
.jagged-sim-container h3 { font-size: 1.05rem; }
.jagged-sim-container p,
.jagged-sim-container li,
.jagged-sim-container dd,
.jagged-sim-container dt,
.jagged-sim-container td,
.jagged-sim-container th,
.jagged-sim-container label,
.jagged-sim-container summary,
.jagged-sim-container legend { color: var(--jf-text); }
.jagged-sim-container p { margin: 0 0 var(--jf-s3); max-width: 72ch; }
.jagged-sim-container small { font-size: 0.875rem; }
.jagged-sim-container strong { font-weight: 750; }
.jagged-sim-container a { color: var(--jf-cyan); text-decoration: underline; text-underline-offset: 3px; }
.jagged-sim-container a:hover { color: var(--jf-text); }
.jagged-sim-container .jf-num { font-variant-numeric: tabular-nums; }

/* Focus: 3px white ring outside the element, with a dark gap so it reads on any fill (2.4.13) */
.jagged-sim-container :is(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
    outline: 3px solid var(--jf-focus);
    outline-offset: 3px;
    box-shadow: 0 0 0 3px var(--jf-bg);
}
.jagged-sim-container :is(h2, h3)[tabindex="-1"]:focus { outline: none; }
.jagged-sim-container :is(h2, h3)[tabindex="-1"]:focus-visible { outline: 3px solid var(--jf-focus); outline-offset: 4px; }

/* Skip link */
.jagged-sim-container .jf-skip {
    position: absolute;
    left: var(--jf-s4);
    top: -200px;
    z-index: 5;
    background: var(--jf-amber-fill);
    color: var(--jf-on-amber);
    font-weight: 750;
    padding: var(--jf-s3) var(--jf-s4);
    border-radius: var(--jf-radius-sm);
    text-decoration: none;
}
.jagged-sim-container .jf-skip:focus { top: var(--jf-s4); }

/* Hero */
.jagged-sim-container .jf-hero {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 240px);
    align-items: end;
    gap: var(--jf-s5);
    background: var(--jf-surface);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius);
    padding: var(--jf-s5) var(--jf-s6);
    margin-bottom: var(--jf-s4);
    overflow: hidden;
}
.jagged-sim-container .jf-kicker {
    color: var(--jf-amber);
    font-weight: 700;
    font-size: 0.875rem;
    letter-spacing: 0.04em;
    margin-bottom: var(--jf-s2);
}
.jagged-sim-container .jf-title {
    font-size: clamp(1.9rem, 3.2vw, 2.6rem);
    font-weight: 800;
    margin-bottom: var(--jf-s2);
}
.jagged-sim-container .jf-sub { color: var(--jf-text-2); font-size: 1.075rem; margin: 0; }
.jagged-sim-container .jf-hero-art { position: relative; height: 96px; }
.jagged-sim-container .jf-ridge {
    position: absolute;
    inset: 0;
    z-index: 1;
    background: var(--jf-amber-fill);
    clip-path: polygon(0 100%, 0 70%, 9% 38%, 16% 62%, 27% 14%, 35% 55%, 44% 30%, 52% 78%, 61% 20%, 70% 48%, 78% 6%, 86% 60%, 93% 34%, 100% 52%, 100% 100%);
    opacity: 0.9;
}
.jagged-sim-container .jf-ridge.jf-ridge-2 {
    z-index: 2;
    background: #2d5a80;
    clip-path: polygon(0 100%, 0 86%, 12% 64%, 22% 80%, 31% 52%, 41% 74%, 50% 58%, 60% 88%, 69% 60%, 80% 76%, 90% 50%, 100% 70%, 100% 100%);
    opacity: 1;
}

/* Stepper */
.jagged-sim-container .jf-stepper {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: var(--jf-s4);
    margin-bottom: var(--jf-s4);
}
.jagged-sim-container .jf-counter {
    margin: 0;
    padding: var(--jf-s2) var(--jf-s4);
    background: var(--jf-surface);
    border: 1px solid var(--jf-line-strong);
    border-radius: 999px;
    font-weight: 700;
    white-space: nowrap;
}
.jagged-sim-container .jf-counter #currentDay,
.jagged-sim-container .jf-counter #maxPeriods { color: var(--jf-amber); font-variant-numeric: tabular-nums; }
.jagged-sim-container .jf-steps {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--jf-s2);
}
.jagged-sim-container .jf-step {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: auto auto;
    column-gap: var(--jf-s2);
    align-items: center;
    padding: var(--jf-s2) var(--jf-s3);
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius-sm);
}
.jagged-sim-container .jf-step-dot {
    grid-row: 1 / span 2;
    width: 32px; height: 32px;
    border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center;
    font-weight: 800;
    border: 2px solid var(--jf-line-strong);
    color: var(--jf-text-2);
}
.jagged-sim-container .jf-step-name { font-weight: 700; font-size: 0.95rem; color: var(--jf-text-2); line-height: 1.3; }
.jagged-sim-container .jf-step-state { font-size: 0.875rem; color: var(--jf-text-3); line-height: 1.3; }
.jagged-sim-container .jf-step.is-current { border-color: var(--jf-amber-fill); background: var(--jf-surface-3); }
.jagged-sim-container .jf-step.is-current .jf-step-dot { background: var(--jf-amber-fill); border-color: var(--jf-amber-fill); color: var(--jf-on-amber); }
.jagged-sim-container .jf-step.is-current .jf-step-name { color: var(--jf-text); }
.jagged-sim-container .jf-step.is-current .jf-step-state { color: var(--jf-amber); font-weight: 700; }
.jagged-sim-container .jf-step.is-done .jf-step-dot { border-color: var(--jf-green); color: var(--jf-green); }
.jagged-sim-container .jf-step.is-done .jf-step-state { color: var(--jf-green); }

/* KPI cards */
.jagged-sim-container .jf-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--jf-s3);
    margin: 0 0 var(--jf-s4);
}
.jagged-sim-container .jf-kpi {
    position: relative;
    background: var(--jf-surface);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius);
    padding: var(--jf-s4) var(--jf-s4) var(--jf-s3) calc(var(--jf-s4) + 6px);
    overflow: hidden;
}
.jagged-sim-container .jf-kpi::before {
    content: "";
    position: absolute; left: 0; top: 0; bottom: 0;
    width: 6px;
    background: var(--jf-cyan);
}
.jagged-sim-container .jf-kpi-trust::before { background: var(--jf-green); }
.jagged-sim-container .jf-kpi-fit::before { background: var(--jf-amber-fill); }
.jagged-sim-container .jf-kpi-score::before { background: var(--jf-violet); }
.jagged-sim-container .jf-kpi dt { font-size: 0.875rem; font-weight: 700; color: var(--jf-text-2); margin-bottom: var(--jf-s1); }
.jagged-sim-container .jf-kpi dd { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--jf-s2); }
.jagged-sim-container .jf-kpi-val { font-size: 2.5rem; font-weight: 800; line-height: 1.1; color: var(--jf-text); font-variant-numeric: tabular-nums; }
.jagged-sim-container .jf-kpi-note { font-size: 0.875rem; color: var(--jf-text-3); }
.jagged-sim-container .jf-up { color: var(--jf-green); font-weight: 700; }
.jagged-sim-container .jf-down { color: var(--jf-red); font-weight: 700; }

/* Layout */
.jagged-sim-container .jf-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 340px);
    gap: var(--jf-s4);
    align-items: stretch;
}
.jagged-sim-container .jf-main,
.jagged-sim-container .jf-side { min-width: 0; display: flex; flex-direction: column; gap: var(--jf-s4); }
.jagged-sim-container .jf-plan { position: sticky; top: var(--jf-s3); z-index: 1; }

.jagged-sim-container .jf-panel {
    background: var(--jf-surface);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius);
    padding: var(--jf-s5);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
}
.jagged-sim-container .jf-help { color: var(--jf-text-2); font-size: 0.95rem; }

/* Briefing */
.jagged-sim-container .jf-brief { border-top: 4px solid var(--jf-amber-fill); }
.jagged-sim-container .jf-scenario-text p { color: var(--jf-text); }
.jagged-sim-container .jf-facts { list-style: none; margin: var(--jf-s3) 0 0; padding: 0; display: grid; gap: var(--jf-s2); }
.jagged-sim-container .jf-facts li {
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius-sm);
    padding: var(--jf-s2) var(--jf-s3);
    max-width: 80ch;
}
.jagged-sim-container .jf-facts li strong { color: var(--jf-amber); }
.jagged-sim-container .jf-news {
    margin: 0 0 var(--jf-s4);
    padding: var(--jf-s3) var(--jf-s4);
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line);
    border-left: 6px solid var(--jf-red);
    border-radius: var(--jf-radius-sm);
}
.jagged-sim-container .jf-news-title { color: var(--jf-red); font-weight: 750; margin-bottom: var(--jf-s1); }
.jagged-sim-container .jf-news ul { margin: 0; padding-left: 1.25rem; }

.jagged-sim-container details { border-radius: var(--jf-radius-sm); }
.jagged-sim-container summary {
    cursor: pointer;
    font-weight: 700;
    min-height: 44px;
    display: flex;
    align-items: center;
    gap: var(--jf-s2);
    padding: var(--jf-s2) var(--jf-s3);
    border: 1px solid var(--jf-line-strong);
    border-radius: var(--jf-radius-sm);
    background: var(--jf-surface-2);
    list-style: none;
}
.jagged-sim-container summary::-webkit-details-marker { display: none; }
.jagged-sim-container summary::before { content: "+"; font-weight: 800; color: var(--jf-amber); width: 1ch; }
.jagged-sim-container details[open] > summary::before { content: "\2212"; }
.jagged-sim-container summary:hover { background: var(--jf-surface-3); }
.jagged-sim-container .jf-howto { margin-top: var(--jf-s3); }
.jagged-sim-container .jf-howto-body { padding: var(--jf-s3) var(--jf-s2) 0; }
.jagged-sim-container .jf-howto-body ol { margin: 0 0 var(--jf-s3); padding-left: 1.4rem; }
.jagged-sim-container .jf-howto-body li { margin-bottom: var(--jf-s1); max-width: 78ch; }
.jagged-sim-container .jf-example {
    border-left: 4px solid var(--jf-cyan);
    padding: var(--jf-s2) var(--jf-s3);
    background: var(--jf-surface-2);
    border-radius: 0 var(--jf-radius-sm) var(--jf-radius-sm) 0;
}

/* Decisions */
.jagged-sim-container .jf-decide { border-top: 4px solid var(--jf-cyan); }
.jagged-sim-container .jf-decide-intro { color: var(--jf-text-2); }
.jagged-sim-container .jf-errors {
    margin: 0 0 var(--jf-s4);
    padding: var(--jf-s3) var(--jf-s4);
    background: #2a1416;
    border: 2px solid var(--jf-red);
    border-radius: var(--jf-radius-sm);
}
.jagged-sim-container .jf-errors p { margin: 0 0 var(--jf-s1); font-weight: 750; color: var(--jf-red); }
.jagged-sim-container .jf-errors ul { margin: 0; padding-left: 1.25rem; }
.jagged-sim-container .jf-errors li,
.jagged-sim-container .jf-errors a { color: var(--jf-text); }

.jagged-sim-container .jf-tasks {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--jf-s3);
}
.jagged-sim-container fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.jagged-sim-container .jf-task {
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius);
    padding: var(--jf-s4);
}
.jagged-sim-container .jf-task.is-missing { border: 2px solid var(--jf-red); }
.jagged-sim-container .jf-task.is-set { border-color: var(--jf-line-strong); }

/* The platform hides every legend (visually on Express pages, display:none elsewhere); these are visible titles */
.jagged-sim-container legend.jf-task-legend,
.jagged-sim-container legend.jf-seg-legend,
.jagged-sim-container legend.jf-pipe-legend {
    display: block;
    position: static;
    width: auto;
    height: auto;
    margin: 0;
    padding: 0;
    overflow: visible;
    clip: auto;
    white-space: normal;
    border: 0;
    float: left;
    width: 100%;
    line-height: 1.35;
}
/* A floated legend renders inside the fieldset instead of on its top border */
.jagged-sim-container fieldset > legend + * { clear: both; }
.jagged-sim-container legend.jf-task-legend { font-size: 1.075rem; font-weight: 800; margin-bottom: var(--jf-s2); }
.jagged-sim-container legend.jf-seg-legend { font-size: 0.875rem; font-weight: 700; color: var(--jf-text-2); margin-bottom: var(--jf-s2); }
.jagged-sim-container .jf-task-meta { display: flex; flex-wrap: wrap; gap: var(--jf-s2); margin-bottom: var(--jf-s3); }
.jagged-sim-container .jf-chip {
    display: inline-block;
    padding: 2px var(--jf-s2);
    font-size: 0.875rem;
    color: var(--jf-text-2);
    background: var(--jf-surface-3);
    border: 1px solid var(--jf-line);
    border-radius: 999px;
    font-variant-numeric: tabular-nums;
}
.jagged-sim-container .jf-task-grid { display: grid; gap: var(--jf-s3); }

/* Segmented options: the native radio covers its label, so clicks, keys and assistive tech all hit the real control */
.jagged-sim-container .jf-seg { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--jf-s2); }
.jagged-sim-container .jf-seg-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.jagged-sim-container .jf-seg-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.jagged-sim-container .jf-opt { position: relative; display: flex; margin: 0; min-width: 0; }
.jagged-sim-container .jf-opt input {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    opacity: 0;
    cursor: pointer;
    z-index: 1;
}
.jagged-sim-container .jf-opt input + span {
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    justify-content: center;
    gap: var(--jf-s2);
    width: 100%;
    min-height: 44px;
    padding: var(--jf-s2) var(--jf-s3);
    border: 1px solid var(--jf-line-strong);
    border-radius: var(--jf-radius-sm);
    background: var(--jf-surface);
    color: var(--jf-text);
    font-weight: 600;
    font-size: 0.95rem;
    line-height: 1.3;
    text-align: center;
}
.jagged-sim-container .jf-seg-v .jf-opt input + span { flex-wrap: wrap; row-gap: 0; }
.jagged-sim-container .jf-opt input + span::before {
    content: "";
    flex: 0 0 auto;
    width: 12px; height: 12px;
    border-radius: 50%;
    border: 2px solid var(--jf-line-strong);
}
.jagged-sim-container .jf-opt input:hover + span { background: var(--jf-surface-3); border-color: var(--jf-text-3); }
.jagged-sim-container .jf-opt input:checked + span {
    background: var(--jf-amber-fill);
    border: 2px solid var(--jf-amber-fill);
    color: var(--jf-on-amber);
    font-weight: 800;
}
.jagged-sim-container .jf-opt input:checked + span::before { background: var(--jf-on-amber); border-color: var(--jf-on-amber); }
.jagged-sim-container .jf-opt input:checked + span .jf-opt-meta { color: var(--jf-on-amber); }
.jagged-sim-container .jf-opt input:focus-visible { outline: none; box-shadow: none; }
.jagged-sim-container .jf-opt input:focus-visible + span { outline: 3px solid var(--jf-focus); outline-offset: 3px; box-shadow: 0 0 0 3px var(--jf-bg); }
.jagged-sim-container .jf-opt input:disabled { cursor: not-allowed; }
.jagged-sim-container .jf-opt input:disabled + span { border-style: dashed; color: var(--jf-text-3); }
.jagged-sim-container .jf-opt input:checked:disabled + span { color: var(--jf-on-amber); }
.jagged-sim-container .jf-opt-meta { color: var(--jf-text-3); font-weight: 600; font-variant-numeric: tabular-nums; }

.jagged-sim-container .jf-task-foot { margin-top: var(--jf-s3); display: grid; gap: var(--jf-s1); }
.jagged-sim-container .jf-probe,
.jagged-sim-container .jf-gate {
    display: inline-flex;
    align-items: center;
    gap: var(--jf-s2);
    min-height: 44px;
    margin: 0;
    padding: var(--jf-s1) var(--jf-s3) var(--jf-s1) var(--jf-s2);
    border: 1px dashed var(--jf-line-strong);
    border-radius: var(--jf-radius-sm);
    color: var(--jf-amber);
    font-weight: 700;
    cursor: pointer;
    width: fit-content;
    max-width: 100%;
}
.jagged-sim-container .jf-probe input,
.jagged-sim-container .jf-gate input { width: 22px; height: 22px; margin: 0; accent-color: var(--jf-amber-fill); flex: 0 0 auto; cursor: pointer; }
.jagged-sim-container .jf-probe:hover,
.jagged-sim-container .jf-gate:hover { background: var(--jf-surface-3); }
.jagged-sim-container .jf-probe.is-used { border-style: solid; border-color: var(--jf-amber-fill); }
.jagged-sim-container .jf-probe.is-off { color: var(--jf-text-3); cursor: not-allowed; }
.jagged-sim-container .jf-probe-out { margin: 0; color: var(--jf-amber); font-weight: 650; }
.jagged-sim-container .jf-probe-out:empty,
.jagged-sim-container .jf-task-plan:empty { display: none; }
.jagged-sim-container .jf-task-plan { margin: 0; color: var(--jf-text-2); font-size: 0.95rem; font-variant-numeric: tabular-nums; }

/* Pipeline */
.jagged-sim-container .jf-pipe { list-style: none; margin: 0; padding: 0; display: grid; gap: 0; }
.jagged-sim-container .jf-pipe > li { position: relative; padding-left: 28px; }
.jagged-sim-container .jf-pipe > li::before {
    content: "";
    position: absolute;
    left: 10px; top: 0; bottom: 0;
    width: 3px;
    background: var(--jf-line-strong);
}
.jagged-sim-container .jf-pipe-step > fieldset {
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line);
    border-radius: var(--jf-radius);
    padding: var(--jf-s3) var(--jf-s4);
    margin: var(--jf-s2) 0;
}
.jagged-sim-container .jf-pipe-step.is-missing > fieldset { border: 2px solid var(--jf-red); }
.jagged-sim-container legend.jf-pipe-legend { font-weight: 800; font-size: 1rem; margin-bottom: var(--jf-s2); display: flex; align-items: center; gap: var(--jf-s2); }
.jagged-sim-container .jf-pipe-num {
    display: inline-flex; align-items: center; justify-content: center;
    width: 28px; height: 28px; border-radius: 50%;
    background: var(--jf-cyan); color: var(--jf-on-amber); font-weight: 800; font-size: 0.95rem;
}
.jagged-sim-container .jf-pipe-gate { padding-top: var(--jf-s1); padding-bottom: var(--jf-s1); }
.jagged-sim-container .jf-gate { color: var(--jf-cyan); }
.jagged-sim-container .jf-gate input { accent-color: var(--jf-cyan); }
.jagged-sim-container .jf-pipe-client { padding-top: var(--jf-s2); padding-bottom: var(--jf-s2); }
.jagged-sim-container .jf-pipe-client span {
    display: inline-block;
    padding: var(--jf-s2) var(--jf-s4);
    border: 2px solid var(--jf-violet);
    border-radius: 999px;
    color: var(--jf-violet);
    font-weight: 800;
}
.jagged-sim-container .jf-pipe-client::before { bottom: 50%; }
.jagged-sim-container .jf-forecast {
    margin-top: var(--jf-s4);
    padding: var(--jf-s4);
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line-strong);
    border-radius: var(--jf-radius);
}
.jagged-sim-container .jf-forecast.is-missing { border: 2px solid var(--jf-red); }
.jagged-sim-container .jf-forecast-label { display: block; font-weight: 750; margin-bottom: var(--jf-s2); max-width: 72ch; }
.jagged-sim-container .jf-forecast-row { display: flex; align-items: center; gap: var(--jf-s2); margin-bottom: var(--jf-s2); }
.jagged-sim-container input[type="number"],
.jagged-sim-container textarea {
    background: var(--jf-bg);
    color: var(--jf-text);
    border: 1px solid var(--jf-line-strong);
    border-radius: var(--jf-radius-sm);
    font: inherit;
    min-height: 44px;
    padding: var(--jf-s2) var(--jf-s3);
}
.jagged-sim-container input[type="number"] { width: 7.5rem; font-size: 1.25rem; font-weight: 750; font-variant-numeric: tabular-nums; }
.jagged-sim-container .jf-forecast-unit { font-size: 1.25rem; font-weight: 750; color: var(--jf-text-2); }
.jagged-sim-container [aria-invalid="true"] { border: 2px solid var(--jf-red); }

.jagged-sim-container .jf-note { margin-top: var(--jf-s4); }
.jagged-sim-container .jf-note label { display: block; font-weight: 650; color: var(--jf-text-2); margin-bottom: var(--jf-s2); max-width: 72ch; }
.jagged-sim-container .jf-note textarea { width: 100%; resize: vertical; }

/* Actions */
.jagged-sim-container .jf-actions { display: flex; flex-wrap: wrap; gap: var(--jf-s3); margin-top: var(--jf-s4); align-items: center; }
.jagged-sim-container .jf-btn {
    min-height: 48px;
    padding: var(--jf-s2) var(--jf-s5);
    border-radius: var(--jf-radius-sm);
    font-weight: 800;
    font-size: 1rem;
    line-height: 1.3;
    cursor: pointer;
}
.jagged-sim-container .jf-btn-primary,
.jagged-sim-container .jf-btn-primary:focus,
.jagged-sim-container .jf-btn-primary:visited {
    background: var(--jf-amber-fill);
    border: 2px solid var(--jf-amber-fill);
    color: var(--jf-on-amber);
}
.jagged-sim-container .jf-btn-primary:hover { background: var(--jf-amber-fill-hover); border-color: var(--jf-amber-fill-hover); color: var(--jf-on-amber); }
.jagged-sim-container .jf-btn-ghost,
.jagged-sim-container .jf-btn-ghost:focus {
    background: transparent;
    border: 2px solid var(--jf-line-strong);
    color: var(--jf-text);
}
.jagged-sim-container .jf-btn-ghost:hover { background: var(--jf-surface-3); color: var(--jf-text); }
.jagged-sim-container .jf-btn:disabled { cursor: not-allowed; border-style: dashed; }
.jagged-sim-container .jf-btn-primary:disabled { background: var(--jf-surface-3); border-color: var(--jf-line-strong); color: var(--jf-text-2); }

/* Side: plan meters, evidence, norms, glossary */
.jagged-sim-container .jf-side .jf-panel { padding: var(--jf-s4); }
.jagged-sim-container .jf-meter { margin-bottom: var(--jf-s3); }
.jagged-sim-container .jf-meter-head { display: flex; justify-content: space-between; gap: var(--jf-s2); font-size: 0.95rem; }
.jagged-sim-container .jf-meter-head span:first-child { color: var(--jf-text-2); font-weight: 650; }
.jagged-sim-container .jf-meter-head span:last-child { font-weight: 800; font-variant-numeric: tabular-nums; text-align: right; }
.jagged-sim-container .jf-bar { position: relative; height: 12px; margin-top: var(--jf-s1); background: #24344f; border-radius: 999px; overflow: hidden; }
.jagged-sim-container .jf-bar-fill { position: absolute; left: 0; top: 0; bottom: 0; background: var(--jf-amber-fill); border-radius: 999px; }
.jagged-sim-container .jf-bar-fill.is-over { background: repeating-linear-gradient(135deg, #ff8f8f 0 6px, #e06666 6px 12px); }
.jagged-sim-container .jf-bar-mark { position: absolute; top: -2px; bottom: -2px; width: 3px; background: var(--jf-text); }
.jagged-sim-container .jf-meter-note { font-size: 0.875rem; color: var(--jf-text-3); margin: var(--jf-s1) 0 0; }
.jagged-sim-container .jf-meter-note.is-warn { color: var(--jf-red); font-weight: 700; }
.jagged-sim-container .jf-intel-list { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--jf-s2); }
.jagged-sim-container .jf-intel-list li { background: var(--jf-surface-2); border: 1px solid var(--jf-line); border-radius: var(--jf-radius-sm); padding: var(--jf-s2) var(--jf-s3); font-size: 0.95rem; }
.jagged-sim-container .jf-intel-task { display: block; font-weight: 750; }
.jagged-sim-container .jf-intel-val { color: var(--jf-amber); font-weight: 750; }
.jagged-sim-container .jf-intel-src { display: block; color: var(--jf-text-3); font-size: 0.875rem; }
.jagged-sim-container .jf-stale { color: var(--jf-red); font-weight: 700; }
.jagged-sim-container .jf-gloss dt { font-weight: 750; color: var(--jf-amber); margin-top: var(--jf-s2); }
.jagged-sim-container .jf-gloss dd { margin: 0 0 var(--jf-s1); color: var(--jf-text-2); font-size: 0.95rem; }
.jagged-sim-container .jf-glossary details > div { padding: var(--jf-s2) var(--jf-s1) 0; }

/* Tables */
.jagged-sim-container .jf-table-wrap { overflow-x: auto; border-radius: var(--jf-radius-sm); }
.jagged-sim-container .jf-table { width: 100%; border-collapse: collapse; font-size: 0.95rem; font-variant-numeric: tabular-nums; }
.jagged-sim-container .jf-table caption { caption-side: top; text-align: left; color: var(--jf-text-2); font-weight: 650; padding: 0 0 var(--jf-s2); }
.jagged-sim-container .jf-table th,
.jagged-sim-container .jf-table td { padding: var(--jf-s2) var(--jf-s3); border-bottom: 1px solid var(--jf-line); text-align: left; vertical-align: top; }
.jagged-sim-container .jf-table thead th { color: var(--jf-text-2); font-size: 0.875rem; font-weight: 750; background: var(--jf-surface-2); border-bottom: 2px solid var(--jf-line-strong); }
.jagged-sim-container .jf-table td.jf-r,
.jagged-sim-container .jf-table th.jf-r { text-align: right; }
.jagged-sim-container .jf-table tbody tr:hover { background: var(--jf-surface-3); }

/* Status tags: icon + word, never colour alone */
.jagged-sim-container .jf-tag { display: inline-flex; align-items: center; gap: 4px; font-weight: 750; white-space: nowrap; }
.jagged-sim-container .jf-tag-ok { color: var(--jf-green); }
.jagged-sim-container .jf-tag-warn { color: var(--jf-amber); }
.jagged-sim-container .jf-tag-bad { color: var(--jf-red); }
.jagged-sim-container .jf-tag-info { color: var(--jf-cyan); }

/* Results of the last quarter */
.jagged-sim-container .jf-results { border-top: 4px solid var(--jf-violet); }
.jagged-sim-container .jf-res-top { display: flex; flex-wrap: wrap; gap: var(--jf-s3); margin-bottom: var(--jf-s4); }
.jagged-sim-container .jf-stat { flex: 1 1 150px; background: var(--jf-surface-2); border: 1px solid var(--jf-line); border-radius: var(--jf-radius-sm); padding: var(--jf-s3); }
.jagged-sim-container .jf-stat-label { display: block; font-size: 0.875rem; color: var(--jf-text-2); font-weight: 650; }
.jagged-sim-container .jf-stat-val { display: block; font-size: 1.5rem; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1.25; }
.jagged-sim-container .jf-stat-sub { display: block; font-size: 0.875rem; color: var(--jf-text-3); }
.jagged-sim-container .jf-callout {
    margin: var(--jf-s3) 0;
    padding: var(--jf-s3) var(--jf-s4);
    background: var(--jf-surface-2);
    border: 1px solid var(--jf-line);
    border-left: 6px solid var(--jf-cyan);
    border-radius: var(--jf-radius-sm);
}
.jagged-sim-container .jf-callout p:last-child { margin-bottom: 0; }
.jagged-sim-container .jf-callout-bad { border-left-color: var(--jf-red); }
.jagged-sim-container .jf-callout-warn { border-left-color: var(--jf-amber-fill); }
.jagged-sim-container .jf-callout-ok { border-left-color: var(--jf-green); }
.jagged-sim-container .jf-callout-title { font-weight: 800; margin-bottom: var(--jf-s1); }

/* History */
.jagged-sim-container .jf-history { margin-top: var(--jf-s4); }
.jagged-sim-container .jf-chart-wrap { position: relative; height: 280px; width: 100%; margin-bottom: var(--jf-s2); }

/* Debrief */
.jagged-sim-container .jf-debrief { border-top: 4px solid var(--jf-amber-fill); }
.jagged-sim-container .jf-db-hero { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--jf-s5); align-items: center; margin-bottom: var(--jf-s4); }
.jagged-sim-container .jf-ring {
    width: 148px; height: 148px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center; flex-direction: column;
    background: conic-gradient(var(--jf-amber-fill) calc(var(--jf-pct, 0) * 1%), #24344f 0);
    position: relative;
}
.jagged-sim-container .jf-ring::after { content: ""; position: absolute; inset: 12px; border-radius: 50%; background: var(--jf-surface); }
.jagged-sim-container .jf-ring-val,
.jagged-sim-container .jf-ring-max { position: relative; z-index: 1; font-variant-numeric: tabular-nums; }
.jagged-sim-container .jf-ring-val { font-size: 2.75rem; font-weight: 850; line-height: 1; }
.jagged-sim-container .jf-ring-max { font-size: 0.95rem; color: var(--jf-text-2); font-weight: 700; }
.jagged-sim-container .jf-tier { font-size: 1.4rem; font-weight: 800; color: var(--jf-amber); margin: 0 0 var(--jf-s1); }
.jagged-sim-container .jf-subscores { display: flex; flex-wrap: wrap; gap: var(--jf-s2); margin: var(--jf-s2) 0 0; padding: 0; list-style: none; }
.jagged-sim-container .jf-subscores li { background: var(--jf-surface-2); border: 1px solid var(--jf-line); border-radius: 999px; padding: 2px var(--jf-s3); font-weight: 650; }
.jagged-sim-container .jf-db-section { margin-top: var(--jf-s5); }
.jagged-sim-container .jf-db-section > h3 { border-bottom: 1px solid var(--jf-line); padding-bottom: var(--jf-s2); }
.jagged-sim-container .jf-db-list { margin: 0; padding-left: 1.25rem; }
.jagged-sim-container .jf-db-list li { margin-bottom: var(--jf-s2); max-width: 80ch; }
.jagged-sim-container .jf-mistake { margin: 0 0 var(--jf-s3); padding: var(--jf-s3) var(--jf-s4); background: var(--jf-surface-2); border: 1px solid var(--jf-line); border-left: 6px solid var(--jf-red); border-radius: var(--jf-radius-sm); }
.jagged-sim-container .jf-mistake-name { font-weight: 800; color: var(--jf-red); margin-bottom: var(--jf-s1); }
.jagged-sim-container .jf-good { border-left-color: var(--jf-green); }
.jagged-sim-container .jf-good .jf-mistake-name { color: var(--jf-green); }
.jagged-sim-container .jf-quote { margin: 0 0 var(--jf-s2); padding: var(--jf-s2) var(--jf-s3); border-left: 3px solid var(--jf-line-strong); color: var(--jf-text-2); font-style: italic; }

/* Completion modal content: rendered by the platform outside the container, so it carries its own colours */
.jagged-sim-cm {
    background: #101a2c;
    color: #f3f6fb;
    border-radius: 14px;
    padding: 24px;
    text-align: left;
    font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    line-height: 1.6;
}
.jagged-sim-cm h3,
.jagged-sim-cm h4,
.jagged-sim-cm p,
.jagged-sim-cm li,
.jagged-sim-cm strong { color: #f3f6fb; }
.jagged-sim-cm h3 { font-size: 1.25rem; margin: 0 0 8px; }
.jagged-sim-cm h4 { font-size: 1rem; margin: 16px 0 6px; }
.jagged-sim-cm .jagged-sim-cm-score { font-size: 3rem; font-weight: 850; line-height: 1; color: #ffcf70; font-variant-numeric: tabular-nums; }
.jagged-sim-cm .jagged-sim-cm-max { font-size: 1.1rem; color: #cdd7e7; font-weight: 700; }
.jagged-sim-cm .jagged-sim-cm-verdict { font-size: 1.15rem; font-weight: 800; color: #93dbff; margin: 6px 0 10px; }
.jagged-sim-cm .jagged-sim-cm-kpis { display: flex; flex-wrap: wrap; gap: 8px 18px; margin: 0 0 8px; padding: 0; list-style: none; }
.jagged-sim-cm .jagged-sim-cm-kpis li { color: #cdd7e7; }
.jagged-sim-cm ul,
.jagged-sim-cm ol { padding-left: 20px; margin: 0; }
.jagged-sim-cm .jagged-sim-cm-note { color: #cdd7e7; border-top: 1px solid #2b3d5c; padding-top: 10px; margin-top: 14px; }

/* Responsive */
@media (max-width: 1100px) {
    .jagged-sim-container .jf-layout { grid-template-columns: minmax(0, 1fr); }
    .jagged-sim-container .jf-plan { position: static; }
    .jagged-sim-container .jf-side { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .jagged-sim-container .jf-side > h2 { grid-column: 1 / -1; }
}
@media (max-width: 860px) {
    .jagged-sim-container .jf-seg-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .jagged-sim-container { padding: var(--jf-s3); border-radius: 0; }
    .jagged-sim-container .jf-hero { grid-template-columns: minmax(0, 1fr); padding: var(--jf-s4); }
    .jagged-sim-container .jf-hero-art { height: 48px; }
    .jagged-sim-container .jf-stepper { grid-template-columns: minmax(0, 1fr); }
    .jagged-sim-container .jf-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .jagged-sim-container .jf-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .jagged-sim-container .jf-tasks { grid-template-columns: minmax(0, 1fr); }
    .jagged-sim-container .jf-side { grid-template-columns: minmax(0, 1fr); }
    .jagged-sim-container .jf-panel { padding: var(--jf-s4); }
    .jagged-sim-container .jf-db-hero { grid-template-columns: minmax(0, 1fr); justify-items: start; }
}
@media (max-width: 420px) {
    .jagged-sim-container .jf-kpi-val { font-size: 2rem; }
    .jagged-sim-container .jf-step { padding: var(--jf-s2); }
    .jagged-sim-container .jf-step-dot { width: 28px; height: 28px; }
    .jagged-sim-container .jf-btn { width: 100%; }
    .jagged-sim-container .jf-seg-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .jagged-sim-container .jf-seg-3 { grid-template-columns: minmax(0, 1fr); }
}

/* 2.3.3 Animation from Interactions */
@media (prefers-reduced-motion: reduce) {
    .jagged-sim-container *,
    .jagged-sim-container *::before,
    .jagged-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Windows high contrast and other forced-colour modes */
@media (forced-colors: active) {
    .jagged-sim-container .jf-opt input + span,
    .jagged-sim-container .jf-panel,
    .jagged-sim-container .jf-task,
    .jagged-sim-container .jf-kpi { border: 1px solid CanvasText; }
    .jagged-sim-container .jf-opt input:checked + span { border: 3px solid Highlight; background: Highlight; color: HighlightText; forced-color-adjust: none; }
    .jagged-sim-container .jf-opt input:checked + span::before { background: HighlightText; border-color: HighlightText; }
    .jagged-sim-container .jf-bar-fill { background: Highlight; forced-color-adjust: none; }
    .jagged-sim-container .jf-ridge { background: CanvasText; }
}

/* More contrast on request */
@media (prefers-contrast: more) {
    .jagged-sim-container { --jf-line: #7489ad; --jf-text-2: #e6edf7; --jf-text-3: #d5deec; background-image: none; }
}

/* Print the debrief legibly */
@media print {
    .jagged-sim-container { background: #ffffff; color: #000000; padding: 0; }
    .jagged-sim-container .jf-panel,
    .jagged-sim-container .jf-kpi { background: #ffffff; box-shadow: none; border-color: #000000; }
    .jagged-sim-container * { color: #000000 !important; }
    .jagged-sim-container .jf-decide,
    .jagged-sim-container .jf-side,
    .jagged-sim-container .jf-hero-art,
    .jagged-sim-container .jf-skip { display: none !important; }
}

