            ds.frontierFit = al.length ? Math.round(al.reduce((s, r) => s + r.map, 0) / al.length) : 0;
            ds.efficiency = al.length ? Math.round(al.reduce((s, r) => s + r.eff, 0) / al.length) : 0;
            ds.performance = { overallScore: overall, outcome: outcome, process: proc.score, tier: this._tier(overall) };
            ds.processParts = proc.parts;
        }

        _mistakes(ds) {
            const P = (ds.periods || []).filter(Boolean);
            const al = P.filter((r) => r.kind === 'alloc');
            const q4 = P[3] && P[3].kind === 'pipeline' ? P[3] : null;
            const out = [];
            if (al[0] && al[0].alloc) {
                const a = al[0].alloc;
                if (a.market.mode === 'human' || (a.memo.mode !== 'human' && a.memo.ver !== 'full')) out.push({ id: 'difficulty', q: 1 });
            }
            const leaks = [];
            P.forEach((r) => { (r.surfaced || []).forEach((s) => leaks.push(s)); });
            if (al[2] && al[2].escaped && al[2].escaped.length && !q4) al[2].escaped.forEach((e) => leaks.push({ task: e.task, from: 3 }));
            if (leaks.length) out.push({ id: 'fluency', q: leaks[0].from, leaks: leaks });
            const uniformQs = al.filter((r) => {
                if (!r.alloc) return false;
                const n = {};
                TASK_KEYS.forEach((k) => { n[r.alloc[k].ver] = (n[r.alloc[k].ver] || 0) + 1; });
                return Object.keys(n).some((v) => n[v] >= 5);
            });
            if (uniformQs.length >= 2) out.push({ id: 'uniform', q: uniformQs[0].p });
            const overload = al.filter((r) => r.deg > 0);
            if (overload.length) out.push({ id: 'overload', q: overload[0].p });
            if (al[1] && al[1].slip) out.push({ id: 'slip', q: 2 });
            if (al[2] && al[2].alloc && al[1] && al[1].alloc) {
                const humans = TASK_KEYS.filter((k) => al[2].alloc[k].mode === 'human').length;
                if (humans >= 5) out.push({ id: 'freeze', q: 3 });
                else if (!(al[2].probes || []).length && this._changed(al[1].alloc, al[2].alloc) <= 1) out.push({ id: 'frozen', q: 3 });
            }
            if (q4) {
                const over = q4.forecast !== null && q4.forecast - q4.raw * 100 >= 15;
                if (q4.client >= 0.10 || over) out.push({ id: 'chain', q: 4 });
                if (q4.sight === 0) out.push({ id: 'nosight', q: 4 });
                if (q4.hoursUsed >= 50) out.push({ id: 'peoplechain', q: 4 });
            }
            return out;
        }

        // ---------- required methods ----------

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    trust: 72,
                    frontierFit: 0,
                    efficiency: 0,
                    version: 2,
                    periods: [],
                    probesNow: { p: 1, tasks: [] },
                    processParts: {},
                    performance: { overallScore: 0, outcome: 0, process: 0, tier: 'lost' }
                };
            }
            const ds = state.domainState;
            if (!Array.isArray(ds.periods)) ds.periods = [];
            if (!ds.probesNow || typeof ds.probesNow !== 'object') ds.probesNow = { p: ds.periods.length + 1, tasks: [] };
            if (!state.decisions || typeof state.decisions !== 'object') state.decisions = {};
            try { this._refreshAll({ sync: true }); } catch (e) { /* the DOM may not be ready yet */ }
        }

        validateDecisions(decisions) {
            const st = this._state();
            const live = !st || decisions === st.decisions;
            if (st && this._isComplete(st)) return false;
            const p = this._period(st);
            const read = this._readControls(p);
            if (read.missing.length) {
                if (live) { this._showErrors(read.missing); this._pending = true; }
                return false;
            }
            if (live) this._clearErrors();
            if (p <= 3) {
                decisions.alloc = read.alloc;
                decisions.probes = (st && st.domainState.probesNow && st.domainState.probesNow.p === p) ? st.domainState.probesNow.tasks.slice(0, this.PROBES_PER_Q) : [];
            } else {
                decisions.pipe = read.pipe;
                decisions.gates = read.gates;
                decisions.forecast = read.forecast;
            }
            decisions.note = read.note;
            decisions.qp = p;
            return true;
        }

        isSubmitPending() {
            const v = this._pending;
            this._pending = false;
            return v;
        }

        calculateResults(state) {
            const ds = state.domainState;
            const p = this._clamp(state.currentPeriod || 1, 1, 4);
            const rec = p <= 3 ? this._calcAllocation(ds, p, state.decisions) : this._calcPipeline(ds, state.decisions);
            ds.periods[p - 1] = rec;
            ds.periods.length = p;
            ds.probesNow = { p: p + 1, tasks: [] };
            this._recompute(ds);
            return { period: p, score: ds.score, quarter: { score: rec.score, hours: Math.round(rec.hoursUsed), trust: rec.trustAfter, kind: rec.kind } };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod', (v) => String(this._clamp(Number(v) || 1, 1, 4)));
            uiManager.bind('maxPeriods', 'maxPeriods', (v) => String(Number(v) || 4));
            if (!this._wired) {
                this._wired = true;
                const root = this._el('jf-root');
                if (root) {
                    root.addEventListener('change', (e) => { try { this._onControl(e); } catch (err) { /* keep the page alive */ } });
                    root.addEventListener('input', (e) => { try { if (e.target && (e.target.id === 'jf-forecast' || e.target.id === 'jf-note')) this._onControl(e); } catch (err) { /* keep the page alive */ } });
                    root.addEventListener('click', (e) => { try { this._onClick(e); } catch (err) { /* keep the page alive */ } });
                }
                const sim = this._fw();
                if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                    sim.eventBus.on('period:submitted', () => { try { this._afterSubmit(); } catch (e) { /* keep the page alive */ } });
                    sim.eventBus.on('period:undone', () => { try { this._refreshAll({ sync: true }); } catch (e) { /* keep the page alive */ } });
                    sim.eventBus.on('framework:initialized', () => { try { this._refreshAll({ sync: true }); } catch (e) { /* keep the page alive */ } });
                }
                document.addEventListener('express:langchanged', () => {
                    try {
                        const live = this._el('jf-live');
                        if (live) live.textContent = '';
                        this._refreshAll({ sync: false, charts: true });
                    } catch (e) { /* keep the page alive */ }
                });
            }
            try { this._refreshAll({ sync: true }); } catch (e) { /* keep the page alive */ }
        }

        // ---------- charts ----------

        getChartConfig() {
            return {
                frontierChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Quarter score', data: [], borderColor: '#cdbdff', backgroundColor: '#cdbdff', borderWidth: 3, pointStyle: 'circle', pointRadius: 6, tension: 0.2, fill: false },
                            { label: 'Client trust', data: [], borderColor: '#93e6b5', backgroundColor: '#93e6b5', borderWidth: 3, borderDash: [8, 5], pointStyle: 'triangle', pointRadius: 7, tension: 0.2, fill: false },
                            { label: 'Delivery efficiency', data: [], borderColor: '#93dbff', backgroundColor: '#93dbff', borderWidth: 3, borderDash: [2, 4], pointStyle: 'rect', pointRadius: 6, tension: 0.2, fill: false }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        animation: false,
                        plugins: { legend: { labels: { color: '#cdd7e7', font: { size: 14 }, usePointStyle: true } } },
                        scales: {
                            y: { min: 0, max: 100, ticks: { color: '#b4c2d8', font: { size: 13 } }, grid: { color: 'rgba(116,137,173,0.35)' } },
                            x: { ticks: { color: '#b4c2d8', font: { size: 13 } }, grid: { color: 'rgba(116,137,173,0.2)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state && state.domainState ? state.domainState : {};
            const P = (ds.periods || []).filter(Boolean);
            return {
                frontierChart: {
                    labels: P.map((r, i) => this._qs(i + 1)),
                    datasets: [
                        { label: this._t('chart_score'), data: P.map((r) => r.score) },
                        { label: this._t('chart_trust'), data: P.map((r) => r.trustAfter) },
                        { label: this._t('chart_eff'), data: P.map((r) => Math.round(r.eff)) }
                    ]
                }
            };
        }

        // ---------- summary, debrief, hints ----------

        getPerformanceSummary(history) {
            const st = this._state();
            const ds = st && st.domainState ? st.domainState : null;
            if (!ds || !(ds.periods || []).length) return {};
            const perf = ds.performance || {};
            return {
                overallScore: perf.overallScore || 0,
                performance: perf.tier || this._tier(perf.overallScore || 0),
                performanceLabel: this._t('tier_' + (perf.tier || 'lost')),
                outcomeScore: perf.outcome || 0,
                processScore: perf.process || 0,
                finalTrust: ds.trust,
                insights: this._insights(ds).slice(0, 5)
            };
        }

        formatCompletionMessage(summary) {
            const st = this._state();
            const ds = st && st.domainState ? st.domainState : null;
            if (!ds) return '';
            return '<div class="jagged-sim-cm" lang="' + this._lang() + '">' + this._debriefHtml(ds, false) + '</div>';
        }

        getHint(state, results) {
            const ds = state && state.domainState ? state.domainState : null;
            if (!ds || !results) return null;
            const p = typeof results.period === 'number' ? results.period : (ds.periods || []).length;
            const rec = (ds.periods || [])[p - 1];
            if (!rec || rec.kind !== 'alloc') return null;
            const dr = this._drain(rec);
            return this._t(dr.problem ? 'hint_lead' : 'hint_lead_ok') + ' ' + dr.text;
        }

        // ---------- reading and syncing controls ----------

        _radio(name) {
            const els = document.querySelectorAll('input[type="radio"][name="' + name + '"]');
            for (let i = 0; i < els.length; i++) { if (els[i].checked) return els[i].value; }
            return null;
        }

        _setRadio(name, value) {
            const els = document.querySelectorAll('input[type="radio"][name="' + name + '"]');
            for (let i = 0; i < els.length; i++) els[i].checked = (value !== null && value !== undefined && els[i].value === String(value));
        }

        _readControls(p) {
            const missing = [];
            const noteEl = this._el('jf-note');
            const note = noteEl ? String(noteEl.value || '').slice(0, 280) : '';
            if (p <= 3) {
                const alloc = {};
                this.TASKS.forEach((t) => {
                    const mode = this._radio('mode_' + t.key);
                    const ver = this._radio('ver_' + t.key);
                    if (!mode || !this.MODE[mode]) missing.push({ kind: 'mode', key: t.key });
                    if (!ver || !this.VER[ver]) missing.push({ kind: 'ver', key: t.key });
                    alloc[t.key] = { mode: mode, ver: ver };
                });
                return { alloc: alloc, note: note, missing: missing };
            }
            const pipe = {};
            STEP_KEYS.forEach((k, i) => {
                const v = this._radio('pipe_' + k);
                if (!v || !this.STEP[v]) missing.push({ kind: 'step', key: k, n: i + 1 });
                pipe[k] = v;
            });
            const fEl = this._el('jf-forecast');
            const raw = fEl ? String(fEl.value).trim() : '';
            const f = raw === '' ? NaN : Number(raw);
            if (!Number.isFinite(f) || f < 0 || f > 100 || Math.round(f) !== f) missing.push({ kind: 'forecast' });
            const gm = this._el('gate_mid'), gf = this._el('gate_final');
            return { pipe: pipe, gates: { mid: !!(gm && gm.checked), final: !!(gf && gf.checked) }, forecast: Number.isFinite(f) ? f : null, note: note, missing: missing };
        }

        _syncControls(st) {
            const ds = st.domainState;
            const p = this._period(st);
            const dec = st.decisions || {};
            const same = dec.qp === p;
            if (p <= 3) {
                let src = null;
                if (same && dec.alloc) src = dec.alloc;
                else if (p > 1 && ds.periods[p - 2] && ds.periods[p - 2].alloc) src = ds.periods[p - 2].alloc;
                this.TASKS.forEach((t) => {
                    const a = src && src[t.key] ? src[t.key] : null;
                    this._setRadio('mode_' + t.key, a ? a.mode : null);
                    this._setRadio('ver_' + t.key, a ? a.ver : null);
                });
                this._carried = !(same && dec.alloc) && p > 1;
            } else {
                STEP_KEYS.forEach((k) => this._setRadio('pipe_' + k, same && dec.pipe ? dec.pipe[k] : null));
                const gm = this._el('gate_mid'), gf = this._el('gate_final'), fe = this._el('jf-forecast');
                if (gm) gm.checked = !!(same && dec.gates && dec.gates.mid);
                if (gf) gf.checked = !!(same && dec.gates && dec.gates.final);
                if (fe) fe.value = same && dec.forecast !== null && dec.forecast !== undefined ? String(dec.forecast) : '';
                this._carried = false;
            }
            const noteEl = this._el('jf-note');
            if (noteEl) noteEl.value = same && dec.note ? String(dec.note) : '';
            this._syncProbes(st);
        }

        _syncProbes(st) {
            const ds = st.domainState;
            const p = this._period(st);
            const used = ds.probesNow && ds.probesNow.p === p ? ds.probesNow.tasks : [];
            const left = this.PROBES_PER_Q - used.length;
            const done = this._isComplete(st) || p > 3;
            this.TASKS.forEach((t) => {
                const box = this._el('probe_' + t.key);
                const lab = box ? box.closest('label') : null;
                const out = this._el('probe_' + t.key + '_out');
                const isUsed = used.indexOf(t.key) >= 0;
                if (box) {
                    box.checked = isUsed;
                    box.disabled = done || isUsed || left <= 0;
                    if (out) box.setAttribute('aria-describedby', out.id);
                }
                if (lab) {
                    lab.classList.toggle('is-used', isUsed);
                    lab.classList.toggle('is-off', !isUsed && (left <= 0 || done));
                }
                if (out) {
                    if (isUsed) out.textContent = this._t('probe_reading', { v: Math.round(this._aiq(t, p) * 100) });
                    else if (left <= 0 && !done) out.textContent = this._t('probe_none_left');
                    else out.textContent = '';
                }
            });
        }

        _saveDraft(st, p) {
            const read = this._readControls(p);
            const d = st.decisions || (st.decisions = {});
            d.qp = p;
            if (p <= 3) d.alloc = read.alloc;
            else { d.pipe = read.pipe; d.gates = read.gates; d.forecast = read.forecast; }
            d.note = read.note;
        }

        _onControl(e) {
            const st = this._state();
            const el = e.target;
            if (!st || !st.domainState || !el || this._isComplete(st)) return;
            const p = this._period(st);
            const id = el.id || '';
            if (el.type === 'checkbox' && id.indexOf('probe_') === 0) {
                const key = id.slice(6);
                const ds = st.domainState;
                if (!ds.probesNow || ds.probesNow.p !== p) ds.probesNow = { p: p, tasks: [] };
                if (el.checked && p <= 3 && ds.probesNow.tasks.indexOf(key) < 0 && ds.probesNow.tasks.length < this.PROBES_PER_Q && this._task(key)) {
                    ds.probesNow.tasks.push(key);
                    this._announce(this._t('probe_announce', { task: this._tn(key), v: Math.round(this._aiq(this._task(key), p) * 100) }));
                }
                this._syncProbes(st);
            }
            this._saveDraft(st, p);
            this._markGroups(p, false);
            if (!this._el('jf-errors').hidden) {
                const read = this._readControls(p);
                if (read.missing.length) this._showErrors(read.missing, true); else this._clearErrors();
            }
            this._renderTaskPlans(st);
            this._renderPlan(st);
        }

        _onClick(e) {
            const a = e.target && e.target.closest ? e.target.closest('a[data-jf-focus]') : null;
            if (!a) return;
            e.preventDefault();
            const target = this._el(a.getAttribute('data-jf-focus'));
            if (!target) return;
            const inp = target.matches && target.matches('input') ? target : target.querySelector('input:not([disabled])');
            if (inp) inp.focus();
        }

        _markGroups(p, strict) {
            const read = this._readControls(p);
            const miss = {};
            read.missing.forEach((m) => { miss[(m.kind === 'mode' || m.kind === 'ver') ? 'task_' + m.key : m.kind === 'step' ? 'step_' + m.key : 'forecast'] = 1; });
            this.TASKS.forEach((t) => {
                const card = this._el('jf-task-' + t.key);
                if (!card) return;
                const isMissing = !!miss['task_' + t.key];
                card.classList.toggle('is-set', !isMissing);
                if (strict) card.classList.toggle('is-missing', isMissing);
                else if (!isMissing) card.classList.remove('is-missing');
            });
            const steps = document.querySelectorAll('.jf-pipe-step');
            STEP_KEYS.forEach((k, i) => {
                const li = steps[i];
                if (!li) return;
                const isMissing = !!miss['step_' + k];
                if (strict) li.classList.toggle('is-missing', isMissing);
                else if (!isMissing) li.classList.remove('is-missing');
            });
            const fc = document.querySelector('.jf-forecast');
            const fe = this._el('jf-forecast');
            if (fc && fe) {
                const bad = !!miss.forecast;
                if (strict) { fc.classList.toggle('is-missing', bad); fe.setAttribute('aria-invalid', bad ? 'true' : 'false'); }
                else if (!bad) { fc.classList.remove('is-missing'); fe.setAttribute('aria-invalid', 'false'); }
            }
        }

        _showErrors(missing, quiet) {
            const box = this._el('jf-errors');
            if (!box) return;
            const items = missing.map((m) => {
                let text, name = null;
                if (m.kind === 'mode') { text = this._t('err_mode', { task: this._tn(m.key) }); name = 'mode_' + m.key; }
                else if (m.kind === 'ver') { text = this._t('err_ver', { task: this._tn(m.key) }); name = 'ver_' + m.key; }
                else if (m.kind === 'step') { text = this._t('err_step', { n: m.n, step: this._t('step_' + m.key) }); name = 'pipe_' + m.key; }
                else { text = this._t('err_forecast'); }
                let target = 'jf-forecast';
                if (name) {
                    const radio = document.querySelector('input[name="' + name + '"]');
                    target = radio ? (radio.id || (radio.id = 'jf-focus-' + name)) : null;
                }
                return '<li>' + (target ? '<a href="#' + target + '" data-jf-focus="' + target + '">' + this._esc(text) + '</a>' : this._esc(text)) + '</li>';
            });
            box.innerHTML = '<p>' + this._esc(this._tp('err_title', missing.length)) + '</p><ul>' + items.join('') + '</ul>';
            box.hidden = false;
            this._markGroups(this._period(this._state()), true);
            if (!quiet) {
                try { box.scrollIntoView({ block: 'center' }); } catch (e) { /* old browsers */ }
                const first = box.querySelector('a');
                if (first) { try { first.focus(); } catch (e) { /* none */ } }
            }
        }

        _clearErrors() {
            const box = this._el('jf-errors');
            if (box) { box.hidden = true; box.innerHTML = ''; }
            document.querySelectorAll('.jagged-sim-container .is-missing').forEach((n) => n.classList.remove('is-missing'));
            const fe = this._el('jf-forecast');
            if (fe) fe.setAttribute('aria-invalid', 'false');
        }

        _announce(text) {
            const live = this._el('jf-live');
            if (!live || !text) return;
            live.textContent = '';
            const self = this;
            window.setTimeout(() => { live.textContent = text; self._lastAnnounce = text; }, 30);
        }

        _afterSubmit() {
            const st = this._state();
            this._refreshAll({ sync: true });
            if (!st || !st.domainState) return;
            const ds = st.domainState;
            const rec = ds.periods[ds.periods.length - 1];
            if (!rec) return;
            if (this._isComplete(st)) {
                this._announce(this._t('live_done', { s: ds.score }));
                return;
            }
            this._announce(this._t('live_committed', { q: this._qs(rec.p), s: rec.score, next: this._qs(rec.p + 1) }));
            const h = this._el('jf-results-h');
            if (h) { try { h.focus({ preventScroll: false }); h.scrollIntoView({ block: 'start' }); } catch (e) { /* none */ } }
        }

        // ---------- rendering ----------

        _refreshAll(opts) {
            const st = this._state();
            if (!st || !st.domainState || !this._el('jf-root')) return;
            const ds = st.domainState;
            if (!Array.isArray(ds.periods)) ds.periods = [];
            const root = this._el('jf-root');
            root.setAttribute('lang', this._lang());
            const steps = [
                () => { if (opts && opts.sync) this._syncControls(st); else this._syncProbes(st); },
                () => this._renderPanels(st), () => this._renderStepper(st), () => this._renderKpis(st),
                () => this._renderResults(st), () => this._renderBriefing(st), () => this._renderDecideHead(st),
                () => this._renderTaskPlans(st), () => this._renderPlan(st), () => this._renderIntel(st),
                () => this._renderCosts(), () => this._renderGlossary(), () => this._renderHistory(st),
                () => this._renderDebrief(st), () => this._markGroups(this._period(st), false)
            ];
            steps.forEach((fn) => { try { fn(); } catch (e) { /* one panel failing must not blank the others */ } });
            if (opts && opts.charts) { try { const f = this._fw(); if (f && typeof f.updateCharts === 'function') f.updateCharts(); } catch (e) { /* none */ } }
        }

        _renderPanels(st) {
            const done = this._isComplete(st);
            const p = this._period(st);
            const show = (id, on) => { const el = this._el(id); if (el) el.hidden = !on; };
            show('jf-decide', !done);
            show('tasksPanel', !done && p <= 3);
            show('pipelinePanel', !done && p === 4);
            show('jf-debrief', done);
            const brief = document.querySelector('.jf-brief');
            if (brief) brief.hidden = done;
            const plan = this._el('jf-plan');
            if (plan) plan.hidden = done;
            const skip = document.querySelector('.jf-skip');
            if (skip) {
                skip.setAttribute('href', done ? '#jf-debrief-h' : '#jf-decide-h');
                skip.textContent = this._t(done ? 'skip_debrief' : 'skip_link');
            }
        }

        _renderStepper(st) {
            const p = this._period(st);
            const done = this._isComplete(st);
            for (let i = 1; i <= 4; i++) {
                const li = this._el('jf-step-' + i);
                const s = this._el('jf-step-' + i + '-state');
                if (!li) continue;
                const isDone = done || i < p;
                const isNow = !done && i === p;
                li.classList.toggle('is-done', isDone);
                li.classList.toggle('is-current', isNow);
                if (isNow) li.setAttribute('aria-current', 'step'); else li.removeAttribute('aria-current');
                if (s) s.textContent = this._t(isDone ? 'step_done' : isNow ? 'step_now' : 'step_next');
            }
            const cd = this._el('currentDay');
            if (cd) cd.textContent = String(p);
        }

        _renderKpis(st) {
            const ds = st.domainState;
            const P = (ds.periods || []).filter(Boolean);
            const last = P[P.length - 1];
            const lastAl = P.filter((r) => r.kind === 'alloc').slice(-1)[0];
            const set = (id, v) => { const el = this._el(id); if (el) el.textContent = v; };
            const setH = (id, v) => { const el = this._el(id); if (el) el.innerHTML = v; };
            if (!last) {
                set('marginDisplay', '—'); setH('jf-kpi-eff-note', this._esc(this._t('kpi_eff_none')));
                set('trustDisplay', this._n(72)); setH('jf-kpi-trust-note', this._esc(this._t('kpi_trust_start')));
                set('mapDisplay', '—'); setH('jf-kpi-fit-note', this._esc(this._t('kpi_fit_none')));
                set('scoreDisplay', '—'); setH('jf-kpi-score-note', this._esc(this._t('kpi_score_none')));
                return;
            }
            if (last.kind === 'pipeline') {
                set('marginDisplay', this._pct(Math.round(last.econ)));
                setH('jf-kpi-eff-note', this._esc(this._t('kpi_eff_pipe', { h: this._n(last.hoursUsed) })));
            } else {
                set('marginDisplay', this._pct(Math.round(last.eff)));
                setH('jf-kpi-eff-note', this._esc(this._t('kpi_eff_note', { q: this._qs(last.p), h: this._n(Math.round(last.hoursUsed)) })));
            }
            set('trustDisplay', this._n(ds.trust));
            const d = Math.round(last.trustDelta || 0);
            setH('jf-kpi-trust-note', '<span class="' + (d >= 0 ? 'jf-up' : 'jf-down') + '">' + (d >= 0 ? '▲ ' : '▼ ') + this._signed(d) + '</span> ' + this._esc(this._t('kpi_trust_note', { q: this._qs(last.p) })));
            if (lastAl) {
                set('mapDisplay', this._pct(Math.round(lastAl.map)));
                setH('jf-kpi-fit-note', this._esc(this._t('kpi_fit_note', { q: this._qs(lastAl.p) })));
            }
            set('scoreDisplay', this._n(ds.score));
            setH('jf-kpi-score-note', this._esc(this._t('tier_' + (ds.performance && ds.performance.tier ? ds.performance.tier : 'lost'))));
        }

        _outcomeTag(row) {
            if (row.out === 'near') return '<span class="jf-tag jf-tag-warn"><span aria-hidden="true">!</span> ' + this._esc(this._t('out_near')) + '</span>';
            if (row.ver === 'none' && row.mode !== 'human') return '<span class="jf-tag jf-tag-info"><span aria-hidden="true">→</span> ' + this._esc(this._t('out_unreviewed')) + '</span>';
            if (row.ver === 'none') return '<span class="jf-tag jf-tag-info"><span aria-hidden="true">→</span> ' + this._esc(this._t('out_human_unreviewed')) + '</span>';
            return '<span class="jf-tag jf-tag-ok"><span aria-hidden="true">✓</span> ' + this._esc(this._t('out_reviewed')) + '</span>';
        }

        _drain(rec) {
            if (rec.surfaced && rec.surfaced.length) {
                const s = rec.surfaced.slice().sort((a, b) => b.trust - a.trust || b.h - a.h)[0];
                return { problem: true, text: this._t('drain_surfaced', { task: this._tn(s.task), q: this._qs(s.from), h: this._n(s.h), t: s.trust }) };
            }
            if (rec.slip) return { problem: true, text: this._t('drain_slip', { h: this._n(Math.round(rec.hoursUsed)) }) };
            if (rec.deg > 0) return { problem: true, text: this._t('drain_overload', { r: this._n(Math.round(rec.review)), cap: this.REVIEW_CAP }) };
            const near = (rec.rows || []).filter((r) => r.out === 'near');
            if (near.length) return { problem: true, text: this._t('drain_near', { task: this._tn(near[0].task) }) };
            const worst = (rec.rows || []).slice().sort((a, b) => (b.fix + b.rework) - (a.fix + a.rework))[0];
            if (worst && worst.fix + worst.rework >= 6) return { problem: rec.score < 80, text: this._t('drain_rework', { task: this._tn(worst.task), h: this._n(Math.round(worst.fix + worst.rework)) }) };
            const big = (rec.rows || []).slice().sort((a, b) => b.planned - a.planned)[0];
            return { problem: rec.score < 80, text: this._t('drain_hours', { task: this._tn(big.task), h: this._n(Math.round(big.planned)) }) };
        }

        _renderResults(st) {
            const ds = st.domainState;
            const box = this._el('jf-results');
            const body = this._el('jf-results-body');
            const head = this._el('jf-results-h');
            const P = (ds.periods || []).filter(Boolean);
            const rec = P[P.length - 1];
            if (!box || !body) return;
            if (!rec || rec.score === undefined) { box.hidden = true; return; }
            box.hidden = false;
            if (head) head.textContent = this._t('res_heading', { q: this._qs(rec.p), phase: this._t('phase_' + rec.p) });
            let html = '';
            const stat = (label, val, sub) => '<div class="jf-stat"><span class="jf-stat-label">' + this._esc(label) + '</span><span class="jf-stat-val">' + val + '</span>' + (sub ? '<span class="jf-stat-sub">' + sub + '</span>' : '') + '</div>';
            const d = Math.round(rec.trustDelta || 0);
            const trustSub = '<span class="' + (d >= 0 ? 'jf-up' : 'jf-down') + '">' + (d >= 0 ? '▲ ' : '▼ ') + this._signed(d) + '</span> ' + this._esc(this._t('res_from', { v: this._n(rec.trustBefore) }));
            if (rec.kind === 'alloc') {
                html += '<div class="jf-res-top">'
                    + stat(this._t('res_qscore'), this._n(rec.score), this._esc(this._t('res_running', { s: this._n(ds.score) })))
                    + stat(this._t('res_hours'), this._h(rec.hoursUsed), this._esc(this._t('res_hours_sub', { p: this._n(Math.round(rec.planned)), x: this._n(Math.round(rec.fixH + rec.reworkH + rec.remedH)) })))
                    + stat(this._t('res_trust'), this._n(rec.trustAfter), trustSub)
                    + stat(this._t('res_fit'), this._pct(Math.round(rec.map)), this._esc(this._t('res_eff', { e: this._n(Math.round(rec.eff)) })))
                    + '</div>';
                if (rec.surfaced && rec.surfaced.length) {
                    html += '<div class="jf-callout jf-callout-bad"><p class="jf-callout-title"><span aria-hidden="true">✗ </span>' + this._esc(this._t('res_surfaced_title')) + '</p><ul>'
                        + rec.surfaced.map((s) => '<li>' + this._esc(this._t('story_' + s.task)) + ' ' + this._esc(this._t('res_surfaced_cost', { q: this._qs(s.from), h: this._n(s.h), t: s.trust })) + '</li>').join('')
                        + '</ul></div>';
                }
                if (rec.slip) html += '<div class="jf-callout jf-callout-bad"><p class="jf-callout-title"><span aria-hidden="true">✗ </span>' + this._esc(this._t('res_slip_title')) + '</p><p>' + this._esc(this._t('res_slip', { h: this._n(Math.round(rec.hoursUsed)) })) + '</p></div>';
                if (rec.deg > 0) html += '<div class="jf-callout jf-callout-warn"><p class="jf-callout-title"><span aria-hidden="true">! </span>' + this._esc(this._t('res_overload_title')) + '</p><p>' + this._esc(this._t('res_overload', { r: this._n(Math.round(rec.review)), cap: this.REVIEW_CAP })) + '</p></div>';
                html += '<div class="jf-table-wrap" tabindex="0" role="region" aria-label="' + this._esc(this._t('res_table_caption', { q: this._qs(rec.p) })) + '"><table class="jf-table"><caption>' + this._esc(this._t('res_table_caption', { q: this._qs(rec.p) })) + '</caption><thead><tr>'
                    + '<th scope="col">' + this._esc(this._t('col_task')) + '</th><th scope="col">' + this._esc(this._t('col_how')) + '</th>'
                    + '<th scope="col" class="jf-r">' + this._esc(this._t('col_planned')) + '</th><th scope="col" class="jf-r">' + this._esc(this._t('col_fix')) + '</th>'
                    + '<th scope="col" class="jf-r">' + this._esc(this._t('col_rework')) + '</th><th scope="col">' + this._esc(this._t('col_status')) + '</th></tr></thead><tbody>'
                    + (rec.rows || []).map((r) => '<tr><th scope="row">' + this._esc(this._tn(r.task)) + '</th><td>' + this._esc(this._t('mode_' + r.mode)) + ' · ' + this._esc(this._t('ver_' + r.ver)) + '</td>'
                        + '<td class="jf-r">' + this._h(r.planned) + '</td><td class="jf-r">' + this._h(r.fix) + '</td><td class="jf-r">' + this._h(r.rework) + '</td><td>' + this._outcomeTag(r) + '</td></tr>').join('')
                    + '</tbody></table></div>';
                const dr = this._drain(rec);
                html += '<div class="jf-callout"><p class="jf-callout-title">' + this._esc(this._t(dr.problem ? 'hint_title' : 'hint_title_ok')) + '</p><p>' + this._esc(dr.text) + '</p></div>';
                if (rec.p < 3) html += '<p class="jf-help">' + this._esc(this._t('res_footnote')) + '</p>';
            } else {
                html += '<div class="jf-res-top">'
                    + stat(this._t('res_design'), this._n(rec.score), this._esc(this._t('res_running', { s: this._n(ds.score) })))
                    + stat(this._t('res_client_err'), this._pct(rec.client * 100, 1), this._esc(this._t('res_client_err_sub')))
                    + stat(this._t('res_cycle_h'), this._h(rec.hoursUsed), this._esc(this._t('res_cycle_h_sub')))
                    + stat(this._t('res_trust'), this._n(rec.trustAfter), trustSub)
                    + '</div>';
                html += '<div class="jf-callout"><p class="jf-callout-title">' + this._esc(this._t('res_chain_title')) + '</p><p>'
                    + this._esc(this._t('res_chain', { raw: this._pct(rec.raw * 100, 1), f: rec.forecast === null ? '—' : this._pct(rec.forecast), client: this._pct(rec.client * 100, 1) })) + '</p></div>';
                if (rec.surfaced && rec.surfaced.length) {
                    html += '<div class="jf-callout jf-callout-bad"><p class="jf-callout-title"><span aria-hidden="true">✗ </span>' + this._esc(this._t('res_surfaced_title')) + '</p><ul>'
                        + rec.surfaced.map((s) => '<li>' + this._esc(this._t('story_' + s.task)) + ' ' + this._esc(this._t('res_surfaced_trust', { q: this._qs(s.from), t: s.trust })) + '</li>').join('') + '</ul></div>';
                }
                if (rec.sight === 0) html += '<div class="jf-callout jf-callout-warn"><p class="jf-callout-title"><span aria-hidden="true">! </span>' + this._esc(this._t('res_nosight_title')) + '</p><p>' + this._esc(this._t('res_nosight')) + '</p></div>';
            }
            body.innerHTML = html;
        }

        _renderBriefing(st) {
            const ds = st.domainState;
            const p = this._period(st);
            const head = this._el('jf-brief-h');
            const el = this._el('briefingText');
            if (head) head.textContent = this._t('brief_heading', { q: this._qs(p), phase: this._t('phase_' + p) });
            if (!el) return;
            let html = '';
            const prev = p > 1 ? ds.periods[p - 2] : null;
            if (prev && prev.escaped && prev.escaped.length) {
                html += '<div class="jf-news"><p class="jf-news-title"><span aria-hidden="true">✗ </span>' + this._esc(this._t('news_title', { q: this._qs(p - 1) })) + '</p><ul>'
                    + prev.escaped.map((e) => '<li>' + this._esc(this._t('story_' + e.task)) + ' ' + this._esc(p <= 3 ? this._t('news_cost', { h: this._n(e.h), t: this.BLAST[e.blast] }) : this._t('news_cost_trust', { t: this.BLAST[e.blast] })) + '</li>').join('')
                    + '</ul></div>';
            }
            html += '<p>' + this._t('brief_q' + p) + '</p>';
            const facts = [];
            for (let i = 1; i <= 4; i++) { const k = 'facts_q' + p + '_' + i; const v = this._t(k); if (v !== k) facts.push(v); }
            if (facts.length) html += '<ul class="jf-facts">' + facts.map((f) => '<li>' + f + '</li>').join('') + '</ul>';
            el.innerHTML = html;
            const how = this._el('jf-howto-body');
            if (how) {
                how.innerHTML = '<ol>' + [1, 2, 3, 4, 5].map((i) => '<li>' + this._esc(this._t('howto_' + i)) + '</li>').join('') + '</ol>'
                    + '<p class="jf-example"><strong>' + this._esc(this._t('howto_example_title')) + '</strong> ' + this._esc(this._t('howto_example')) + '</p>';
            }
            const det = this._el('jf-howto');
            if (det && !det.__jfInit) { det.__jfInit = true; if (!(ds.periods || []).length) det.open = true; }
        }

        _renderDecideHead(st) {
            const p = this._period(st);
            const head = this._el('jf-decide-h');
            const intro = this._el('jf-decide-intro');
            if (head) head.textContent = this._t(p <= 3 ? 'decide_heading' : 'decide_heading_q4', { q: this._qs(p) });
            if (intro) intro.textContent = this._t(p <= 3 ? (this._carried ? 'decide_intro_carried' : 'decide_intro') : 'decide_intro_q4', { prev: this._qs(p - 1) });
            const lab = this._el('jf-submit-label');
            if (lab) lab.textContent = this._t(p <= 3 ? 'submit_q' : 'submit_q4', { q: this._qs(p) });
        }

        _renderTaskPlans(st) {
            const p = this._period(st);
            if (p > 3) return;
            this.TASKS.forEach((t) => {
                const el = this._el('jf-plan-' + t.key);
                if (!el) return;
                const mode = this._radio('mode_' + t.key), ver = this._radio('ver_' + t.key);
                if (!mode || !ver) { el.textContent = this._t('task_plan_pending'); return; }
                const work = t.hours * this.MODE[mode].cost, rev = t.hours * this.VER[ver].cost;
                el.textContent = this._t('task_plan', { w: this._n(Math.round(work)), r: this._n(Math.round(rev)) });
            });
        }

        _meter(label, valueText, value, max, mark, over, note, warn) {
            const pct = this._clamp(value / max * 100, 0, 100);
            const mk = mark !== null ? '<span class="jf-bar-mark" style="left:' + this._clamp(mark / max * 100, 0, 100).toFixed(1) + '%"></span>' : '';
            return '<div class="jf-meter"><div class="jf-meter-head"><span>' + this._esc(label) + '</span><span>' + this._esc(valueText) + '</span></div>'
                + '<div class="jf-bar" aria-hidden="true"><span class="jf-bar-fill' + (over ? ' is-over' : '') + '" style="width:' + pct.toFixed(1) + '%"></span>' + mk + '</div>'
                + (note ? '<p class="jf-meter-note' + (warn ? ' is-warn' : '') + '">' + this._esc(note) + '</p>' : '') + '</div>';
        }

        _renderPlan(st) {
            const body = this._el('jf-plan-body');
            if (!body) return;
            const ds = st.domainState;
            const p = this._period(st);
            if (this._isComplete(st)) { body.innerHTML = ''; return; }
            let html = '';
            if (p <= 3) {
                const read = this._readControls(p);
                const used = ds.probesNow && ds.probesNow.p === p ? ds.probesNow.tasks.length : 0;
                const prev = p > 1 ? ds.periods[p - 2] : null;
                const remed = prev && prev.escaped ? prev.escaped.reduce((s, e) => s + e.h, 0) : 0;
                const plan = this._plannedHours(read.alloc, used, remed);
                const ref = this.BASELINE - this.NORM[p - 1];
                const refLabel = this._t(p === 2 ? 'plan_ref_cap' : 'plan_ref_rival', { h: ref });
                const overRef = plan.hours > ref;
                const last = prev && prev.kind === 'alloc' ? ' ' + this._t('plan_last', { q: this._qs(p - 1), p: this._n(Math.round(prev.planned)), a: this._n(Math.round(prev.hoursUsed)) }) : '';
                html += this._meter(this._t('plan_hours'), this._t('plan_hours_val', { h: this._n(Math.round(plan.hours)), ref: ref }), plan.hours, 300, ref, overRef && p === 2,
                    refLabel + (remed > 0 ? ' ' + this._t('plan_remed', { h: this._n(Math.round(remed)) }) : '') + ' ' + this._t('plan_hours_note') + last + (plan.set < 6 ? ' ' + this._t('plan_partial', { n: plan.set }) : ''), overRef && p === 2);
                const rev = this._reviewHours(read.alloc);
                const overRev = rev > this.REVIEW_CAP + 1e-9;
                html += this._meter(this._t('plan_review'), this._t('plan_review_val', { r: this._n(Math.round(rev)), cap: this.REVIEW_CAP }), rev, 100, this.REVIEW_CAP, overRev,
                    overRev ? this._t('plan_review_over') : this._t('plan_review_note'), overRev);
                html += this._meter(this._t('plan_probes'), this._t('plan_probes_val', { u: used, n: this.PROBES_PER_Q }), used, this.PROBES_PER_Q, null, false, this._t('plan_probes_note'), false);
                let deleg = 0;
                this.TASKS.forEach((t) => { const a = read.alloc[t.key]; if (a && a.mode && a.mode !== 'human') deleg += t.hours; });
                html += this._meter(this._t('plan_deleg'), this._pct(Math.round(deleg / this.BASELINE * 100)), deleg, this.BASELINE, null, false, this._t('plan_deleg_note'), false);
                const state = (overRef && p === 2 ? 'cap' : '') + (overRev ? 'rev' : '');
                if (state !== this._planState) {
                    if (this._planState !== undefined && state) this._announce(overRev ? this._t('plan_review_over') : this._t('plan_cap_over'));
                    this._planState = state;
                }
            } else {
                const read = this._readControls(4);
                let h = (read.gates.mid ? this.GATE_HOURS : 0) + (read.gates.final ? this.GATE_HOURS : 0), set = 0;
                STEP_KEYS.forEach((k) => { const v = read.pipe[k]; if (v && this.STEP[v]) { h += this.STEP[v].h; set++; } });
                html += this._meter(this._t('plan_cycle'), this._t('plan_cycle_val', { h: this._n(h) }), h, 80, 16, false, this._t('plan_cycle_note') + (set < 5 ? ' ' + this._t('plan_steps_partial', { n: set }) : ''), false);
                html += '<p class="jf-meter-note">' + this._esc(this._t('plan_q4_note')) + '</p>';
            }
            body.innerHTML = html;
        }

        _renderIntel(st) {
            const el = this._el('intelBox');
            if (!el) return;
            const ds = st.domainState;
            const p = this._period(st);
            const items = [];
            items.push({ task: 'market', text: this._t('intel_pilot_market'), src: this._t('intel_src_pilot'), stale: p >= 3 });
            items.push({ task: 'memo', text: this._t('intel_pilot_memo'), src: this._t('intel_src_pilot'), stale: p >= 3 });
            (ds.periods || []).filter(Boolean).forEach((r) => {
                (r.probes || []).forEach((x) => items.push({ task: x.task, text: this._t('intel_reading', { v: x.value }), src: this._t('intel_src_probe', { q: this._qs(r.p) }), stale: r.p <= 2 && p >= 3 }));
            });
            if (ds.probesNow && ds.probesNow.p === p && p <= 3 && !this._isComplete(st)) {
                ds.probesNow.tasks.forEach((k) => items.push({ task: k, text: this._t('intel_reading', { v: Math.round(this._aiq(this._task(k), p) * 100) }), src: this._t('intel_src_probe_now', { q: this._qs(p) }), stale: false }));
            }
            el.innerHTML = '<ul class="jf-intel-list">' + items.map((it) => '<li><span class="jf-intel-task">' + this._esc(this._tn(it.task)) + '</span><span class="jf-intel-val">' + this._esc(it.text) + '</span>'
                + '<span class="jf-intel-src">' + this._esc(it.src) + (it.stale ? ' · <span class="jf-stale">' + this._esc(this._t('intel_stale')) + '</span>' : '') + '</span></li>').join('') + '</ul>'
                + '<p class="jf-meter-note">' + this._esc(this._t('intel_note')) + '</p>';
        }

        _renderCosts() {
            const el = this._el('jf-costs-body');
            if (!el) return;
            const row = (a, b) => '<tr><th scope="row">' + this._esc(a) + '</th><td class="jf-r">' + this._esc(b) + '</td></tr>';
            el.innerHTML = '<table class="jf-table"><caption>' + this._esc(this._t('costs_caption')) + '</caption><tbody>'
                + row(this._t('mode_human'), this._pct(100)) + row(this._t('mode_ai'), this._pct(15)) + row(this._t('mode_centaur'), this._pct(45)) + row(this._t('mode_cyborg'), this._pct(60))
                + row(this._t('ver_spot'), '+' + this._pct(10)) + row(this._t('ver_full'), '+' + this._pct(30))
                + '</tbody></table><p class="jf-meter-note">' + this._esc(this._t('costs_note', { cap: this.REVIEW_CAP })) + '</p>';
        }

        _renderGlossary() {
            const el = this._el('jf-gloss-body');
            if (!el) return;
            const terms = ['frontier', 'bands', 'ai', 'centaur', 'cyborg', 'spot', 'full', 'probe', 'surface', 'capacity', 'gate', 'reliability'];
            const open = el.querySelector('details') && el.querySelector('details').open;
            el.innerHTML = '<details' + (open ? ' open' : '') + '><summary>' + this._esc(this._t('gloss_open', { n: terms.length })) + '</summary><div><dl class="jf-gloss">'
                + terms.map((k) => '<dt>' + this._esc(this._t('gloss_' + k + '_t')) + '</dt><dd>' + this._esc(this._t('gloss_' + k)) + '</dd>').join('') + '</dl></div></details>';
        }

        _renderHistory(st) {
            const ds = st.domainState;
            const P = (ds.periods || []).filter(Boolean);
            const table = this._el('jf-history-table');
            const desc = this._el('jf-chart-desc');
            const canvas = this._el('frontierChart');
            if (canvas) canvas.setAttribute('aria-label', this._t('chart_label'));
            if (desc) {
                desc.textContent = P.length
                    ? this._t('chart_desc', { s: P.map((r) => this._qs(r.p) + ' ' + this._n(r.score)).join(', '), t: P.map((r) => this._qs(r.p) + ' ' + this._n(r.trustAfter)).join(', '), e: P.map((r) => this._qs(r.p) + ' ' + this._n(Math.round(r.eff))).join(', ') })
                    : this._t('chart_empty');
            }
            if (!table) return;
            if (!P.length) { table.innerHTML = '<caption>' + this._esc(this._t('hist_caption')) + '</caption><tbody><tr><td>' + this._esc(this._t('hist_empty')) + '</td></tr></tbody>'; return; }
            const cols = ['col_quarter', 'col_qscore', 'col_hours', 'col_review', 'col_trust', 'col_eff', 'col_fit', 'col_leaks', 'col_near'];
            table.innerHTML = '<caption>' + this._esc(this._t('hist_caption')) + '</caption><thead><tr>' + cols.map((c, i) => '<th scope="col"' + (i ? ' class="jf-r"' : '') + '>' + this._esc(this._t(c)) + '</th>').join('') + '</tr></thead><tbody>'
                + P.map((r) => '<tr><th scope="row">' + this._esc(this._qs(r.p) + ' · ' + this._t('phase_' + r.p)) + '</th>'
                    + '<td class="jf-r">' + this._n(r.score) + '</td>'
                    + '<td class="jf-r">' + this._h(r.hoursUsed) + (r.kind === 'pipeline' ? ' ' + this._esc(this._t('per_cycle')) : '') + '</td>'
                    + '<td class="jf-r">' + (r.kind === 'alloc' ? this._h(r.review) : '—') + '</td>'
                    + '<td class="jf-r">' + this._n(r.trustAfter) + ' (' + this._signed(r.trustDelta) + ')</td>'
                    + '<td class="jf-r">' + this._pct(Math.round(r.eff)) + '</td>'
                    + '<td class="jf-r">' + (r.kind === 'alloc' ? this._pct(Math.round(r.map)) : '—') + '</td>'
                    + '<td class="jf-r">' + this._n((r.surfaced || []).length) + '</td>'
                    + '<td class="jf-r">' + this._n(r.nearMisses || 0) + '</td></tr>').join('') + '</tbody>';
        }

        // ---------- debrief ----------

        _fitMark(pt) {
            if (pt >= 0.75) return '<span class="jf-tag jf-tag-ok"><span aria-hidden="true">✓</span> ' + this._esc(this._t('fit_good')) + '</span>';
            if (pt >= 0.4) return '<span class="jf-tag jf-tag-warn"><span aria-hidden="true">~</span> ' + this._esc(this._t('fit_part')) + '</span>';
            return '<span class="jf-tag jf-tag-bad"><span aria-hidden="true">✗</span> ' + this._esc(this._t('fit_poor')) + '</span>';
        }

        _turningPoint(ds) {
            const P = (ds.periods || []).filter(Boolean);
            if (!P.length) return '';
            const worst = P.slice().sort((a, b) => a.score - b.score)[0];
            let cause;
            if (worst.kind === 'pipeline') {
                if (worst.surfaced && worst.surfaced.length) cause = this._t('tp_surfaced', { task: this._tn(worst.surfaced[0].task), from: this._qs(worst.surfaced[0].from), t: worst.surfaced[0].trust });
                else if (worst.client >= 0.10) cause = this._t('tp_chain', { client: this._pct(worst.client * 100, 1), raw: this._pct(worst.raw * 100, 1) });
                else if (worst.sight === 0) cause = this._t('tp_nosight');
                else if (worst.hoursUsed >= 40) cause = this._t('tp_cycle_hours', { h: this._n(worst.hoursUsed) });
                else cause = this._t('tp_pipe_ok');
            } else if (worst.surfaced && worst.surfaced.length) {
                const s = worst.surfaced[0];
                cause = this._t('tp_surfaced_alloc', { task: this._tn(s.task), from: this._qs(s.from), t: s.trust, h: this._n(s.h) });
            } else if (worst.slip) cause = this._t('tp_slip', { h: this._n(Math.round(worst.hoursUsed)) });
            else if (worst.deg > 0) cause = this._t('tp_overload', { r: this._n(Math.round(worst.review)), cap: this.REVIEW_CAP });
            else if (worst.map < 60) cause = this._t('tp_fit', { f: this._pct(Math.round(worst.map)) });
            else if (worst.eff < 40) cause = this._t('tp_eff', { h: this._n(Math.round(worst.hoursUsed)) });
            else cause = this._t('tp_minor');
            const key = worst.score >= 85 ? 'tp_none' : 'tp_head';
            return this._t(key, { q: this._qs(worst.p), phase: this._t('phase_' + worst.p), s: worst.score }) + ' ' + cause;
        }

        _insights(ds) {
            const P = (ds.periods || []).filter(Boolean);
            const al = P.filter((r) => r.kind === 'alloc');
            const out = [];
            const probes = [];
            al.forEach((r) => (r.probes || []).forEach((x) => probes.push(this._tn(x.task) + ' (' + this._qs(r.p) + ')')));
            out.push(probes.length ? this._tp('ins_probes', probes.length, { list: probes.join(', '), f: this._pct(ds.frontierFit) }) : this._t('ins_probes_none', { f: this._pct(ds.frontierFit) }));
            if (al.length) {
                const within = al.filter((r) => r.review <= this.REVIEW_CAP + 1e-9).length;
                out.push(this._t('ins_review', { k: within, n: al.length, list: al.map((r) => this._qs(r.p) + ' ' + this._h(r.review)).join(', '), cap: this.REVIEW_CAP }));
            }
            const leaks = [];
            P.forEach((r) => (r.surfaced || []).forEach((s) => leaks.push(this._tn(s.task) + ' (' + this._qs(s.from) + ')')));
            const nears = al.reduce((s, r) => s + (r.nearMisses || 0), 0);
            const nearText = nears ? this._tp('ins_nears', nears) : this._t('ins_nears_none');
            out.push((leaks.length ? this._tp('ins_leaks', leaks.length, { list: leaks.join(', ') }) : this._t('ins_noleaks')) + ' ' + nearText);
            if (al[2] && al[2].alloc && al[1]) {
                const a = al[2].alloc.slides;
                out.push(this._t('ins_upgrade', { how: this._t('mode_' + a.mode) + ' · ' + this._t('ver_' + a.ver), f2: this._pct(Math.round(al[1].map)), f3: this._pct(Math.round(al[2].map)) }));
            }
            const q4 = P[3] && P[3].kind === 'pipeline' ? P[3] : null;
            if (q4) out.push(this._t('ins_chain', { raw: this._pct(q4.raw * 100, 1), f: q4.forecast === null ? '—' : this._pct(q4.forecast), client: this._pct(q4.client * 100, 1), h: this._n(q4.hoursUsed) }));
            return out;
        }

        _strengths(ds, mistakes) {
            const P = (ds.periods || []).filter(Boolean);
            const al = P.filter((r) => r.kind === 'alloc');
            const ids = mistakes.map((m) => m.id);
            const out = [];
            if (al[0] && ids.indexOf('difficulty') < 0 && (al[0].probes || []).length) out.push('good_evidence');
            if (ids.indexOf('fluency') < 0 && ids.indexOf('slip') < 0 && al.length === 3) out.push('good_clean');
            if (ids.indexOf('uniform') < 0 && ids.indexOf('overload') < 0 && al.length === 3) out.push('good_portfolio');
            if (al[2] && ids.indexOf('frozen') < 0 && ids.indexOf('freeze') < 0 && (al[2].probes || []).length) out.push('good_remap');
            const q4 = P[3];
            if (q4 && q4.kind === 'pipeline' && ids.indexOf('chain') < 0 && q4.client < 0.05 && q4.sight === 100 && q4.hoursUsed <= 26) out.push('good_chain');
            return out;
        }

        _debriefHtml(ds, full) {
            const perf = ds.performance || {};
            const score = perf.overallScore || 0;
            const tier = perf.tier || 'lost';
            const mistakes = this._mistakes(ds);
            const strengths = this._strengths(ds, mistakes);
            const P = (ds.periods || []).filter(Boolean);
            const al = P.filter((r) => r.kind === 'alloc');
            const leaks = P.reduce((s, r) => s + (r.surfaced || []).length, 0);
            const H = full ? 'h3' : 'h4';
            let html = '';
            if (full) {
                html += '<div class="jf-db-hero"><div class="jf-ring" style="--jf-pct:' + score + '" role="img" aria-label="' + this._esc(this._t('db_score_aria', { s: score })) + '"><span class="jf-ring-val" aria-hidden="true">' + this._n(score) + '</span><span class="jf-ring-max" aria-hidden="true">/100</span></div><div>'
                    + '<p class="jf-tier">' + this._esc(this._t('tier_' + tier)) + '</p><p>' + this._esc(this._t('tier_' + tier + '_d')) + '</p>'
                    + '<ul class="jf-subscores"><li>' + this._esc(this._t('db_outcome', { s: this._n(perf.outcome || 0) })) + '</li><li>' + this._esc(this._t('db_process', { s: this._n(perf.process || 0) })) + '</li>'
                    + '<li>' + this._esc(this._t('db_trust', { t: this._n(ds.trust) })) + '</li><li>' + this._esc(this._t('db_leaks', { n: this._n(leaks) })) + '</li></ul></div></div>';
            } else {
                html += '<h3>' + this._esc(this._t('debrief_heading')) + '</h3>'
                    + '<div class="jagged-sim-cm-score">' + this._n(score) + '<span class="jagged-sim-cm-max">/100</span></div>'
                    + '<div class="jagged-sim-cm-verdict">' + this._esc(this._t('tier_' + tier)) + '</div>'
                    + '<ul class="jagged-sim-cm-kpis"><li>' + this._esc(this._t('db_outcome', { s: this._n(perf.outcome || 0) })) + '</li><li>' + this._esc(this._t('db_process', { s: this._n(perf.process || 0) })) + '</li>'
                    + '<li>' + this._esc(this._t('db_trust', { t: this._n(ds.trust) })) + '</li><li>' + this._esc(this._t('db_leaks', { n: this._n(leaks) })) + '</li></ul>';
            }
            html += '<div class="jf-db-section"><' + H + '>' + this._esc(this._t('db_turning')) + '</' + H + '><p>' + this._esc(this._turningPoint(ds)) + '</p></div>';
            if (mistakes.length) {
                html += '<div class="jf-db-section"><' + H + '>' + this._esc(this._t('db_mistakes')) + '</' + H + '>'
                    + mistakes.map((m) => '<div class="jf-mistake"><p class="jf-mistake-name"><span aria-hidden="true">✗ </span>' + this._esc(this._t('mk_' + m.id)) + '</p><p>' + this._esc(this._t('mk_' + m.id + '_d', { q: this._qs(m.q) })) + '</p></div>').join('') + '</div>';
            }
            if (strengths.length) {
                html += '<div class="jf-db-section"><' + H + '>' + this._esc(this._t('db_mistakes_none')) + '</' + H + '>'
                    + strengths.map((k) => '<div class="jf-mistake jf-good"><p class="jf-mistake-name"><span aria-hidden="true">✓ </span>' + this._esc(this._t(k)) + '</p><p>' + this._esc(this._t(k + '_d')) + '</p></div>').join('') + '</div>';
            }
            html += '<div class="jf-db-section"><' + H + '>' + this._esc(this._t('db_insights')) + '</' + H + '><ul class="jf-db-list">' + this._insights(ds).map((x) => '<li>' + this._esc(x) + '</li>').join('') + '</ul></div>';
            if (full) {
                html += '<div class="jf-db-section"><h3>' + this._esc(this._t('db_truth')) + '</h3><p class="jf-help">' + this._esc(this._t('db_truth_intro')) + '</p><div class="jf-table-wrap" tabindex="0" role="region" aria-label="' + this._esc(this._t('db_truth')) + '"><table class="jf-table"><thead><tr>'
                    + '<th scope="col">' + this._esc(this._t('col_task')) + '</th><th scope="col" class="jf-r">' + this._esc(this._t('col_true12')) + '</th><th scope="col" class="jf-r">' + this._esc(this._t('col_true34')) + '</th>'
                    + al.map((r) => '<th scope="col">' + this._esc(this._t('col_you', { q: this._qs(r.p) })) + '</th>').join('') + '</tr></thead><tbody>'
                    + this.TASKS.map((t) => '<tr><th scope="row">' + this._esc(this._tn(t.key)) + '</th><td class="jf-r">' + this._pct(Math.round(t.aiq[0] * 100)) + ' · ' + this._esc(this._t('band_' + this._band(t.aiq[0]))) + '</td>'
                        + '<td class="jf-r">' + this._pct(Math.round(t.aiq[1] * 100)) + ' · ' + this._esc(this._t('band_' + this._band(t.aiq[1]))) + '</td>'
                        + al.map((r) => { const a = (r.alloc && r.alloc[t.key]) || { mode: 'human', ver: 'none' }; return '<td>' + this._esc(this._t('mode_' + a.mode) + ' · ' + this._t('ver_' + a.ver)) + '<br>' + this._fitMark(this._mapPt(t, a, r.p)) + '</td>'; }).join('') + '</tr>').join('')
                    + '</tbody></table></div></div>';
                const parts = ds.processParts || {};
                const pk = ['evidence', 'remap', 'learn', 'capacity', 'forecast'];
                html += '<div class="jf-db-section"><h3>' + this._esc(this._t('db_process_h')) + '</h3><ul class="jf-db-list">'
                    + pk.filter((k) => parts[k] !== undefined).map((k) => '<li><strong>' + this._esc(this._t('proc_' + k)) + ':</strong> ' + this._pct(Math.round(parts[k] * 100)) + '. ' + this._esc(this._t('proc_' + k + '_d')) + '</li>').join('')
                    + '</ul></div>';
                const notes = P.filter((r) => r.note);
                if (notes.length) html += '<div class="jf-db-section"><h3>' + this._esc(this._t('db_notes')) + '</h3>' + notes.map((r) => '<p class="jf-quote"><strong>' + this._esc(this._qs(r.p)) + ':</strong> ' + this._esc(r.note) + '</p>').join('') + '</div>';
            }
            const qs = ['dq_1', leaks ? 'dq_2' : 'dq_2b', 'dq_3', 'dq_4'];
            html += '<div class="jf-db-section"><' + H + '>' + this._esc(this._t('db_questions')) + '</' + H + '><ol class="jf-db-list">' + qs.slice(0, full ? 4 : 3).map((k) => '<li>' + this._esc(this._t(k)) + '</li>').join('') + '</ol></div>';
            if (!full) html += '<p class="jagged-sim-cm-note">' + this._esc(this._t('cm_more')) + '</p>';
            return html;
        }

        _band(q) { return q >= 0.85 ? 'inside' : q >= 0.65 ? 'contested' : 'outside'; }

        _renderDebrief(st) {
            const body = this._el('jf-debrief-body');
            if (!body) return;
            if (!this._isComplete(st)) { body.innerHTML = ''; return; }
            body.innerHTML = this._debriefHtml(st.domainState, true);
        }

